from pysat.solvers import Glucose3
from pysat.formula import CNF

def var(r, c, v):
    return r * 256 + c * 16 + v + 1

cnf = CNF()

# Each cell has exactly one value
for r in range(16):
    for c in range(16):
        cnf.append([var(r, c, v) for v in range(16)])
        for v1 in range(16):
            for v2 in range(v1 + 1, 16):
                cnf.append([-var(r, c, v1), -var(r, c, v2)])

# Each row has distinct values
for r in range(16):
    for v in range(16):
        cnf.append([var(r, c, v) for c in range(16)])
        for c1 in range(16):
            for c2 in range(c1 + 1, 16):
                cnf.append([-var(r, c1, v), -var(r, c2, v)])

# Each column has distinct values
for c in range(16):
    for v in range(16):
        cnf.append([var(r, c, v) for r in range(16)])
        for r1 in range(16):
            for r2 in range(r1 + 1, 16):
                cnf.append([-var(r1, c, v), -var(r2, c, v)])

# Each 4x4 block has distinct values
for br in range(4):
    for bc in range(4):
        for v in range(16):
            cells = [(br * 4 + i, bc * 4 + j) for i in range(4) for j in range(4)]
            cnf.append([var(r, c, v) for r, c in cells])
            for i in range(len(cells)):
                for j in range(i + 1, len(cells)):
                    r1, c1 = cells[i]
                    r2, c2 = cells[j]
                    cnf.append([-var(r1, c1, v), -var(r2, c2, v)])

# Partial assignment
assignments = {
    5: 6, 13: 14, 14: 15, 18: 7, 22: 3, 26: 15, 27: 16, 33: 10, 34: 11, 42: 3, 
    53: 10, 54: 11, 57: 6, 58: 7, 69: 5, 71: 7, 80: 6, 81: 5, 83: 7, 84: 2, 
    85: 1, 94: 12, 103: 15, 106: 4, 107: 3, 109: 5, 112: 14, 115: 15, 120: 6, 
    135: 6, 136: 11, 140: 15, 141: 16, 148: 3, 150: 1, 170: 1, 175: 6, 185: 8, 
    188: 3, 190: 1, 196: 8, 199: 5, 201: 11, 203: 9, 208: 8, 218: 14, 240: 16, 
    241: 15, 243: 13, 244: 12, 253: 3
}

for idx, val in assignments.items():
    r, c = divmod(idx, 16)
    cnf.append([var(r, c, val - 1)])

solver = Glucose3()
solver.append_formula(cnf.clauses)
if solver.solve():
    model = solver.get_model()
    sol = [0] * 256
    for lit in model:
        if lit > 0:
            lit -= 1
            v = lit % 16
            lit //= 16
            c = lit % 16
            r = lit // 16
            sol[r * 16 + c] = v + 1
    print("SAT")
    print(sol)
else:
    print("UNSAT")
